// Delaney's hand-charted alphabets. GENERATED FROM HER OWN CHARTED LIBRARY.
// DO NOT HAND-EDIT, and never re-chart or re-interpret these glyphs through
// any image/quantisation pipeline -- only layout (position, spacing, line
// breaks) is ever computed from them.
//
// Each glyph is stored as its literal stitch grid: one string per row, where
// '0' = empty, '1' = the main thread colour, '2' = a second thread colour
// (only the Shadow Serif font uses '2'). Glyph width is row length; glyph
// height is row count -- both vary per glyph, so layout must measure each
// glyph rather than assume a fixed cell.
//
// `baseline` is the modal ink-bottom row with glyph boxes TOP-ALIGNED,
// measured from the real data. The only glyphs whose ink falls below it are
// true descenders (g/j/p/q/y) and authentic Copperplate flourishes -- so
// top-aligning boxes yields a correct shared baseline with no hand-authored
// per-glyph metrics.

export type HandFont = {
  id: string;
  label: string;
  /** Tallest glyph in the font; all glyph boxes are top-aligned within it. */
  boxH: number;
  /** Modal ink-bottom row (top-aligned). Descenders sit below this. */
  baseline: number;
  /** 2 = this font uses a second colour (cell value '2'). */
  colours: 1 | 2;
  /** Human-readable coverage, e.g. "A-Z, 0-9". */
  coverage: string;
  /** Characters this font does NOT include, if any. */
  missing: string;
  /** Glyph -> rows of '0'/'1'/'2'. */
  glyphs: Record<string, string[]>;
  /** Per-glyph advance reduction applied AFTER this character, in stitches.
   *  Absent/0 = no change (backward compatible, every existing font is
   *  unaffected by default). This exists because some hand-charted glyphs
   *  (a cursive exit flourish, for example) have real ink that legitimately
   *  extends close to where the next letter starts -- there is no "empty
   *  space" a smarter width calculation could find, because the ink is
   *  actually there. This is a deliberate override, not a computed value,
   *  and each value here has been checked against every other glyph in the
   *  font for hard collisions AND visual crossover (a following letter's
   *  ink landing left of this glyph's ink in the same row) before being set.
   *  Do not add or change a value here without doing the same check. */
  kernAfter?: Record<string, number>;
};

