export function findHandFont(id: string): HandFont | undefined {
  return HAND_FONTS.find((f) => f.id === id);
}

/** Glyph dimensions, measured from the stored rows. */
export function glyphSize(rows: string[]): { w: number; h: number } {
  return { w: rows[0]?.length ?? 0, h: rows.length };
}
